//! Simulated odds for each skirmish scenario, shown on the menu.
//! Generated by `cargo run --release --bin sim -- --rust 25 240` — regenerate after balance changes.

/// First-named fleet's win %, draw % and mean battle minutes.
#[derive(Clone, Copy, Debug)]
pub struct Odds {
    pub win: f32,
    pub draw: f32,
    pub minutes: f32,
}

pub const BATTLES: u32 = 50;
pub const SHIPS: usize = 240;

